import{_ as d,o as r,c as o,a2 as a}from"./chunks/framework.CHeM0PsO.js";const c=JSON.parse('{"title":"03 · 分镜（A 片 · demo 版）","description":"","frontmatter":{},"headers":[],"relativePath":"lab/shuangyu-fries/03-storyboard.md","filePath":"lab/shuangyu-fries/03-storyboard.md","lastUpdated":1787456457000}'),s={name:"lab/shuangyu-fries/03-storyboard.md"};function n(e,t,g,h,l,p){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="_03-·-分镜-a-片-·-demo-版" tabindex="-1">03 · 分镜（A 片 · demo 版） <a class="header-anchor" href="#_03-·-分镜-a-片-·-demo-版" aria-label="Permalink to &quot;03 · 分镜（A 片 · demo 版）&quot;">​</a></h1><blockquote><p>阶段 3 · 分镜 ｜ 2026-08-06 ｜ <strong>内部工作文档，不对客</strong></p></blockquote><div class="warning custom-block"><p class="custom-block-title">已被客户反馈后的 v2 取代</p><p>本页保留为 A 片 demo v1 的历史记录。2026-08-10 客户要求强化制作细节、节奏与工艺完整性，正式修订走 <a href="./03a-a-process-complete-storyboard">03a · A 片工艺完整性版</a>。</p></div><div class="danger custom-block"><p class="custom-block-title">这份分镜是在客户未确认创意核心的情况下写的</p><p><a href="./#待客户确认">待客户确认第 1 条</a>——「原薯鲜切做主标题是否认可」——<strong>至今未回应</strong>。</p><p>项目规范写着「阶段 1 未放行不写分镜」。这次绕过它，理由只有一条：</p><blockquote><p><strong>镜头 1–9 在任何创意方向下都要用到。</strong> 鲜切、低温油炸、多孔断面、脱油、成品质感，无论主标题最后落在「原薯鲜切」还是「VF 工艺」，这批素材一帧都不浪费——变的只是叙事顺序和字幕。</p></blockquote><p><strong>真正会废掉的只有镜头 10（字幕落版）和整体节奏。</strong> 这是可承受的损失，也是这份分镜敢写的全部依据。</p><p>如果客户否掉创意核心，回来改的是排序和字幕，不是重拍。</p></div><h2 id="demo-的用途" tabindex="-1">demo 的用途 <a class="header-anchor" href="#demo-的用途" aria-label="Permalink to &quot;demo 的用途&quot;">​</a></h2><p><strong>不是交付样片，是撬动物料。</strong></p><p>客户已连续两轮回避物料问题（<a href="./">项目首页</a>记录）。继续发催料邮件收益递减，<strong>给他看见东西</strong>是更有效的手段——而这支 demo 被有意设计成「工艺段落完整、产品段落将就」，让缺口自己说话。</p><table tabindex="0"><thead><tr><th></th><th>demo 版</th><th>成片版</th></tr></thead><tbody><tr><td>镜头 1–9</td><td>生成</td><td>同上，精修</td></tr><tr><td><strong>镜头 10 · 产品出镜</strong></td><td><strong>客户渲染图做后期动态</strong></td><td><strong>必须用设计源文件重做</strong></td></tr><tr><td>字幕「80~90℃」</td><td>打上</td><td><strong>须 2b 确认本产品参数后方可保留</strong></td></tr><tr><td>脱油工序呈现</td><td>做</td><td><strong>须 2c 确认本产品确有此工序</strong></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">两条字幕/镜头是故意留的钩子</p><p>「80~90℃」与「离心脱油」目前都只有<a href="./00-brief#客户补充物料-vf-工艺资料">通用技术资料</a>支撑，<strong>未确认适用于本产品</strong>（物料清单 2b、2c）。</p><p>demo 里照做——客户看到自己产品的片子里打着这个温度，会比看到催料邮件更快去问工厂要参数。<strong>让待确认项以画面形式出现在客户眼前，是这支 demo 的第二个用途。</strong></p><p>但成片前必须落实。这条已写进下方每一镜的状态列。</p></div><h2 id="a-片-·-镜头表" tabindex="-1">A 片 · 镜头表 <a class="header-anchor" href="#a-片-·-镜头表" aria-label="Permalink to &quot;A 片 · 镜头表&quot;">​</a></h2><p><strong>总时长 18.5 秒 · 16:9 主机位（另出 9:16 裁切）· 无人声，音效 + 环境音</strong></p><table tabindex="0"><thead><tr><th>#</th><th>时长</th><th>景别</th><th>画面</th><th>光位</th><th>声音</th><th>制作方式</th><th>状态</th></tr></thead><tbody><tr><td><strong>1</strong></td><td>1.5s</td><td>微距特写</td><td>整颗土豆落在木质案板上，表皮带薄土，轻微弹跳后静止</td><td>侧逆光，硬光，勾出表皮质感</td><td>闷响一声「咚」</td><td>图生视频</td><td>✅ 可做</td></tr><tr><td><strong>2</strong></td><td>1.5s</td><td>微距特写</td><td>刀刃切入土豆，切面渗出淀粉汁水，切面纹理清晰</td><td>同上，切面补一点顶光提亮</td><td>清脆切入声</td><td>首尾帧</td><td>✅ 可做</td></tr><tr><td><strong>3</strong></td><td>1.0s</td><td>特写</td><td>切好的土豆条落下，慢动作，条形整齐、边缘带毛刺（<strong>真土豆切的证据</strong>）</td><td>顶光，浅景深</td><td>落下的轻响</td><td>图生视频</td><td>✅ 可做</td></tr><tr><td><strong>4</strong></td><td>2.5s</td><td>中特写</td><td><strong>真空舱内的油面</strong>——油面近乎平静，只有细密小气泡缓慢上升。土豆条悬浮其中</td><td>舱内暖黄单光源，四周暗</td><td>低频嗡鸣，<strong>几乎安静</strong></td><td>首尾帧</td><td>✅ 可做</td></tr><tr><td><strong>5</strong></td><td>2.0s</td><td>微观 / 剖面</td><td>土豆条内部水分被抽离，<strong>孔洞逐渐形成、扩张、连成多孔结构</strong></td><td>内透光，孔洞边缘发亮</td><td>细微的气泡破裂声</td><td>首尾帧</td><td>✅ 可做</td></tr><tr><td><strong>6</strong></td><td>2.0s</td><td>中景</td><td><strong>离心机高速旋转</strong>，油滴被甩向筒壁，薯条逐渐变干爽</td><td>冷白工业光 + 运动模糊</td><td>离心机加速的机械声</td><td>图生视频</td><td>🟡 <strong>须 2c 确认</strong></td></tr><tr><td><strong>7</strong></td><td>2.0s</td><td>微距特写</td><td>一根薯条脆立起，<strong>强逆光穿透断面</strong>，多孔结构被光点亮</td><td><strong>强逆光</strong>，背景压暗</td><td>环境安静，留白</td><td>首尾帧</td><td>✅ 可做</td></tr><tr><td><strong>8</strong></td><td>1.5s</td><td>微距特写</td><td>薯条脆被掰断，<strong>断面炸开细碎颗粒</strong>，慢动作</td><td>侧硬光，突出碎屑飞溅</td><td><strong>「咔嚓」——音效主角</strong></td><td>首尾帧</td><td>✅ 可做</td></tr><tr><td><strong>9</strong></td><td>2.0s</td><td>特写</td><td>成品堆叠掉落，金黄偏浅（<strong>不是深褐色</strong>），表面干爽无油光</td><td>柔和顶光 + 侧补光</td><td>薯条相互碰撞的沙沙声</td><td>图生视频</td><td>✅ 可做</td></tr><tr><td><strong>10</strong></td><td>2.5s</td><td>中景</td><td><strong>产品包装出镜</strong> + 主标题字幕落版</td><td>影棚布光（后期合成）</td><td>音乐收尾</td><td><strong>后期动态，不生成</strong></td><td>🔴 <strong>demo 将就</strong></td></tr></tbody></table><h3 id="字幕" tabindex="-1">字幕 <a class="header-anchor" href="#字幕" aria-label="Permalink to &quot;字幕&quot;">​</a></h3><table tabindex="0"><thead><tr><th>时点</th><th>字幕</th><th>依据</th><th>状态</th></tr></thead><tbody><tr><td>镜头 4</td><td><strong>80~90℃ 低温油炸</strong></td><td>客户工艺资料</td><td>🟡 <strong>须 2b 确认为本产品参数</strong></td></tr><tr><td>镜头 7</td><td><strong>所以它是脆的</strong></td><td>画面自证</td><td>✅</td></tr><tr><td>镜头 10</td><td><strong>原薯鲜切</strong></td><td>包装上既有文案</td><td>✅ 包装可对应</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">字幕红线</p><p>以下表述<strong>不出现</strong>，与<a href="./01-proposal">提案「内容边界」</a>一致：非油炸、更健康、低脂、0 负担、不含丙烯酰胺、与传统油炸的任何对比。</p><p>镜头 4 之所以敢打温度，是因为<strong>它陈述事实、不作比较</strong>——不出现「传统油炸 180℃」这类参照物。观众心里的对比由他自己完成，屏幕上不摆。</p></div><h2 id="关键镜头的设计意图" tabindex="-1">关键镜头的设计意图 <a class="header-anchor" href="#关键镜头的设计意图" aria-label="Permalink to &quot;关键镜头的设计意图&quot;">​</a></h2><h3 id="镜头-4-低温油炸的视觉特征是「安静」" tabindex="-1">镜头 4：低温油炸的视觉特征是「安静」 <a class="header-anchor" href="#镜头-4-低温油炸的视觉特征是「安静」" aria-label="Permalink to &quot;镜头 4：低温油炸的视觉特征是「安静」&quot;">​</a></h3><p>这一镜最容易做错。<strong>常压油炸的画面是剧烈翻滚、大量白色气泡</strong>——那是水在 100℃ 以上沸腾。</p><p>真空低温不是。负压下水的沸点降低，<strong>油面近乎平静，只有细密小气泡缓慢上升</strong>。</p><div class="tip custom-block"><p class="custom-block-title">这个差异本身就是最好的说服</p><p>不需要并排对比，不需要旁白解释。<strong>观众看过无数油炸镜头，他知道油炸该是什么样子。</strong></p><p>当画面安静得不像油炸时，「这个不一样」的结论他自己会下——而且是<a href="./01-proposal">提案里说的</a>那种「他自己得出的对比」，比屏幕上摆出来的更有说服力，也不踩对比广告的红线。</p></div><h3 id="镜头-5-7-一个原因-一个结果" tabindex="-1">镜头 5 + 7：一个原因，一个结果 <a class="header-anchor" href="#镜头-5-7-一个原因-一个结果" aria-label="Permalink to &quot;镜头 5 + 7：一个原因，一个结果&quot;">​</a></h3><p>镜头 5 讲<strong>孔是怎么来的</strong>（水分抽离 → 形成多孔），镜头 7 讲<strong>孔带来了什么</strong>（光能透过 → 所以脆）。</p><p>两镜必须成对出现，且中间隔着镜头 6。<strong>先看见成因，再看见证据，中间隔一道工序</strong>——这个顺序是因果链能被读懂的关键。</p><p>单放镜头 7 只是好看；有了镜头 5，它才是证明。</p><h3 id="镜头-6-这个产品唯一能正面回应「油炸-油腻」的东西" tabindex="-1">镜头 6：这个产品唯一能正面回应「油炸=油腻」的东西 <a class="header-anchor" href="#镜头-6-这个产品唯一能正面回应「油炸-油腻」的东西" aria-label="Permalink to &quot;镜头 6：这个产品唯一能正面回应「油炸=油腻」的东西&quot;">​</a></h3><p>见 <a href="./00-brief">00-brief 工艺资料裁定</a>。它陈述的是<strong>工序</strong>，不是营养结论——不需要检测数据，合规成本为零。</p><p>而且它有画面、实拍拍不到，是生成技术的优势区间。</p><p><strong>如果 2c 确认本产品没有这道工序，这一镜必须整个删掉</strong>，不能用「看起来像脱油」的画面糊弄。</p><h3 id="镜头-10-为什么坚持不生成" tabindex="-1">镜头 10：为什么坚持不生成 <a class="header-anchor" href="#镜头-10-为什么坚持不生成" aria-label="Permalink to &quot;镜头 10：为什么坚持不生成&quot;">​</a></h3><p><a href="/tools/decision-tree#a1-产品必须精确还原吗">决策树 A1</a> 已经写死：产品需精确还原 → 不要纯生成。</p><p>包装含 logo、注册商标、中文、日文与精确品牌色。<strong>生成模型必然画错</strong>，而客户看到一个假包装只有两种反应，都是坏的：以为我们打算这么做，或者觉得「这个包装看着也行」。</p><p><strong>宁可留一个明显将就的镜头，也不填一个假的。</strong></p><p>demo 做法：客户渲染图 → 去背 → AI 生成背景与光环境 → 后期做推拉、光扫、景深、粒子。<strong>包装本身像素级不变，不经过任何生成模型。</strong></p><div class="warning custom-block"><p class="custom-block-title">日文副标的镜头处理</p><p>已确认日文为纯装饰、与日本无关系（<a href="./#③-日文元素-定性前一律不碰">决议 ③</a>）。</p><p><strong>镜头 10 的角度与景别不刻意突出日文副标</strong>——正面平视即可，不给侧标特写。理由是合规与竞争两条，见决议 ③。</p></div><h2 id="素材复用-b-片从这里剪出" tabindex="-1">素材复用：B 片从这里剪出 <a class="header-anchor" href="#素材复用-b-片从这里剪出" aria-label="Permalink to &quot;素材复用：B 片从这里剪出&quot;">​</a></h2><p><a href="./01-proposal">提案第二节</a>说明过，A 片先做，B 片从中剪出。</p><table tabindex="0"><thead><tr><th>B 片需要</th><th>从哪来</th></tr></thead><tbody><tr><td>撕封口（第一帧）</td><td>❌ <strong>A 片没有，须实物打样件实拍</strong></td></tr><tr><td>断面 / 咔嚓</td><td>镜头 7、8 直接复用</td></tr><tr><td>成品质感</td><td>镜头 9 直接复用</td></tr><tr><td>产品落版</td><td>镜头 10 复用</td></tr></tbody></table><p><strong>B 片的开头这一镜是唯一的硬缺口</strong>，且只能实拍——这也是物料清单第 4 项（实物打样件）必须要到的原因。B 片执行表见 <a href="./04c-b-jimeng-v1">04c · B 片即梦</a> 与 <a href="./04d-b-gemini-v1">04d · B 片 Gemini</a>：撕封口附实拍清单，生成部分附 9:16 Prompt。</p><h2 id="待办与风险" tabindex="-1">待办与风险 <a class="header-anchor" href="#待办与风险" aria-label="Permalink to &quot;待办与风险&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>状态</th></tr></thead><tbody><tr><td>客户确认创意核心（待确认第 1 条）</td><td>⬜ 未回应。否掉则改排序与字幕，不改镜头</td></tr><tr><td>2b · 本产品油温参数</td><td>🟡 未确认。影响镜头 4 字幕能否进成片</td></tr><tr><td>2c · 脱油工序</td><td>🟡 未确认。<strong>不成立则整删镜头 6</strong></td></tr><tr><td>包装设计源文件</td><td>🔴 缺。镜头 10 成片版做不了</td></tr><tr><td>实物打样件</td><td>🔴 缺。B 片开头做不了</td></tr><tr><td>竞品是否鲜切（<a href="./01a-audience-competitors">01a 第三节</a>）</td><td>🔴 未核实。若竞品普遍鲜切，镜头 1–3 的比重要下调</td></tr></tbody></table><hr><p><strong>上一步</strong> ← <a href="./02-materials">02 · 物料清单</a> ｜ <strong>下一步</strong> → <a href="./04-prompts">04 · Prompt 组</a></p>',42)])])}const b=d(s,[["render",n]]);export{c as __pageData,b as default};
